/* RTM v045 fullscreen bootstrap, Bitrix bridge and navigation guard. */
(function(){
'use strict';
var button,channelId='rtm44_'+Math.random().toString(36).slice(2),pendingCalls=new Map(),bridgeReady=false,initQueue=[],realBX24=window.BX24,clients=new Set(),invalidateTimer=0;
function isStandalone(){return window.__RTM_STANDALONE__===true||new URLSearchParams(location.search).get('rtm_fullscreen')==='1'}
function standaloneUrl(){try{var url=new URL(location.href);url.searchParams.set('rtm_fullscreen','1');var material=document.getElementById('userMaterialView')?.dataset.id;if(material){url.searchParams.set('rtm_open','material');url.searchParams.set('id',material)}else if(typeof state!=='undefined'&&state.courseId){url.searchParams.set('course',String(state.courseId))}return url.href}catch(_){return location.href}}
function setPressed(active){if(!button)return;button.setAttribute('aria-pressed',active?'true':'false');button.title=active?'Выйти из полноэкранного режима':'Открыть приложение на весь экран';button.textContent=active?'×':'⛶'}
function cssFullscreen(active){document.body.classList.toggle('v41-app-fullscreen',active);setPressed(active)}
function sameOrigin(event){return event.origin===location.origin}
function resultFacade(payload){return{error:function(){return payload.error||null},error_description:function(){return payload.errorDescription||''},data:function(){return payload.data},more:function(){return!!payload.more}}}
function requestRefresh(){clearTimeout(invalidateTimer);invalidateTimer=setTimeout(function(){if(typeof window.loadAll==='function'&&(typeof state==='undefined'||!state.syncing))window.loadAll(true).catch(function(error){console.warn('Fullscreen refresh failed',error)})},700)}
function installChildBridge(){if(!isStandalone())return;if(!window.opener){window.BX24={init:function(callback){setTimeout(callback,0)},callMethod:function(method,params,callback){callback(resultFacade({error:'BRIDGE_UNAVAILABLE',errorDescription:'Откройте полноэкранный режим из приложения Bitrix24'}))},isAdmin:function(){return false},getDomain:function(){return''}};return}window.BX24={init:function(callback){if(bridgeReady)setTimeout(callback,0);else initQueue.push(callback)},callMethod:function(method,params,callback){var id=channelId+'_'+Date.now()+'_'+Math.random().toString(36).slice(2),timer=setTimeout(function(){pendingCalls.delete(id);callback(resultFacade({error:'BRIDGE_TIMEOUT',errorDescription:'Исходная вкладка Bitrix24 не отвечает'}))},25000);pendingCalls.set(id,{callback:callback,timer:timer});window.opener.postMessage({rtmV45:'call',id:id,method:method,params:params||{}},location.origin)},isAdmin:function(){return!!window.__rtmV45Admin},getDomain:function(){return window.__rtmV45Domain||new URL(document.referrer||location.href).hostname}};window.addEventListener('message',function(event){if(!sameOrigin(event)||event.source!==window.opener||!event.data)return;var message=event.data;if(message.rtmV45==='context'){window.__rtmV45Admin=!!message.admin;window.__rtmV45Domain=message.domain||'';bridgeReady=true;initQueue.splice(0).forEach(function(callback){try{callback()}catch(error){console.error(error)}})}else if(message.rtmV45==='result'){var pending=pendingCalls.get(message.id);if(!pending)return;clearTimeout(pending.timer);pendingCalls.delete(message.id);pending.callback(resultFacade(message))}else if(message.rtmV45==='invalidate')requestRefresh()});window.opener.postMessage({rtmV45:'hello'},location.origin)}
function broadcastInvalidation(){clients.forEach(function(client){try{client.postMessage({rtmV45:'invalidate'},location.origin)}catch(_){clients.delete(client)}})}
function installParentBridge(){if(isStandalone()||!realBX24)return;window.addEventListener('message',function(event){if(!sameOrigin(event)||!event.data)return;var message=event.data;if(message.rtmV45==='hello'){clients.add(event.source);var domain='';try{domain=typeof realBX24.getDomain==='function'?realBX24.getDomain():''}catch(_){}event.source.postMessage({rtmV45:'context',admin:typeof realBX24.isAdmin==='function'&&realBX24.isAdmin(),domain:domain},event.origin);return}if(message.rtmV45!=='call'||typeof realBX24.callMethod!=='function')return;clients.add(event.source);try{realBX24.callMethod(message.method,message.params||{},function(result){var error=result.error&&result.error(),payload={rtmV45:'result',id:message.id,error:error,errorDescription:result.error_description&&result.error_description(),data:result.data&&result.data(),more:result.more&&result.more()};event.source.postMessage(payload,event.origin);if(!error&&/(?:add|update|delete|uploadfile|uploadversion)$/i.test(message.method))setTimeout(broadcastInvalidation,80)})}catch(error){event.source.postMessage({rtmV45:'result',id:message.id,error:'BRIDGE_ERROR',errorDescription:String(error.message||error)},event.origin)}});window.addEventListener('rtm-v45-remote-saved',broadcastInvalidation)}
function toggle(){if(isStandalone()){if(window.opener){window.close();return}if(history.length>1){history.back();return}location.href='/';return}var target=standaloneUrl();if(window.innerWidth<=800){window.open(target,'_top');return}var opened=window.open(target,'_blank');if(!opened)alert('Браузер заблокировал новую вкладку. Разрешите всплывающие окна для приложения.')}
function repairLearningRoute(){if(typeof state==='undefined'||state.uview!=='learn')return;var list=document.getElementById('userCourseListView'),course=document.getElementById('userCourseView'),material=document.getElementById('userMaterialView');if(!list||!course||!material)return;var allHidden=[list,course,material].every(function(node){return node.classList.contains('hidden')});if(allHidden&&typeof window.showUserCourses==='function')window.showUserCourses()}
function installNavigationGuard(){if(typeof window.showUserView!=='function'||window.__rtmV45NavGuard)return;window.__rtmV45NavGuard=true;var base=window.showUserView;window.showUserView=function(view){var result=base.apply(this,arguments);if(view==='learn')setTimeout(repairLearningRoute,0);return result}}
function init(){button=document.getElementById('v41AppFullscreen');if(button)button.onclick=toggle;var standalone=isStandalone();if(standalone)cssFullscreen(true);installNavigationGuard();repairLearningRoute();document.addEventListener('fullscreenchange',function(){if(!document.fullscreenElement&&!standalone)cssFullscreen(false);else setPressed(true)});document.addEventListener('webkitfullscreenchange',function(){setPressed(Boolean(document.webkitFullscreenElement)||standalone)});window.addEventListener('popstate',repairLearningRoute)}
installChildBridge();installParentBridge();
window.__RTM_SHELL_INIT__=init;
})();


