function renderAnalyticsUsers(root,data){root.innerHTML=analyticsTopbar('Поиск по пользователям (имя или email)')+'<div class="stats-grid analytics-stats"><div class="dash-stat"><span>Обученность</span><b>'+avg(data.userRows.map(r=>r.pct))+'%</b></div><div class="dash-stat"><span>Пройдено</span><b>'+sum(data.userRows,'done')+'</b></div><div class="dash-stat"><span>Провалено</span><b>0</b></div><div class="dash-stat"><span>В процессе</span><b>'+sum(data.userRows,'inwork')+'</b></div><div class="dash-stat"><span>Не начато</span><b>'+sum(data.userRows,'notStarted')+'</b></div></div><div class="table-card"><table class="admin-table"><thead><tr><th>Пользователь</th><th>Отделы</th><th>Обученность</th><th>Назначено</th><th>Пройдено</th><th>Провалено</th><th>В процессе</th><th>Не начато</th></tr></thead><tbody id="analyticsUserRows"></tbody></table></div>'; bindAnalyticsTools(()=>renderAnalyticsUsers(root,data)); $('#analyticsUserRows').innerHTML=filteredUsers(data).map(r=>'<tr><td><div class="user-cell"><span class="avatar-mini">'+userAvatarMarkup(r.u)+'</span><b>'+esc(fullName(r.u))+'</b></div></td><td>'+esc(userDepartments(r.u))+'</td><td>'+r.pct+'%</td><td>'+r.assigned+'</td><td>'+r.done+'</td><td>'+r.failed+'</td><td>'+r.inwork+'</td><td>'+r.notStarted+'</td></tr>').join('')}
