function v38RenderMobileMenu(){var canUseAdmin=v38ActualDeveloper(),modeSwitch=$('#modeSwitch');if(modeSwitch)modeSwitch.style.display=v38IsPhone()&&!canUseAdmin?'none':'';var nav=$('#v38MobileNav');if(!nav)return;var admin=state.mode==='admin',html='';if(admin&&!canUseAdmin){setMode('user');return}if(admin){var items=[['dashboard','Дашборд'],['materials','Учебные материалы'],['users','Пользователи'],['database','База данных'],['analytics','Аналитика'],['events','События'],['settings','Настройки'],['info','Информация']];html=items.map(function(x){return '<button data-v38-admin="'+x[0]+'" class="'+(state.aview===x[0]?'active':'')+'">'+x[1]+'</button>'}).join('')+'<div class="v38-mobile-projects"><b>Проекты</b><button data-v38-add-project>+ Новый проект</button>'+activeRows(state.projects).map(function(p){return '<span class="v38-mobile-project-row"><button data-v38-project="'+p.ID+'">'+esc(p.NAME)+'</button><button data-v38-project-menu="'+p.ID+'" aria-label="Настройки проекта '+esc(p.NAME)+'">⚙</button></span>'}).join('')+'<button data-v38-project="trash">Корзина</button></div>'}else html=[['learn','Обучение'],['kb','База знаний'],['profile','Профиль'],['projects','Список материалов']].map(function(x){return '<button data-v38-user="'+x[0]+'" class="'+(state.uview===x[0]?'active':'')+'">'+x[1]+'</button>'}).join('');html+='<div class="v38-mobile-menu-bottom"><button data-v38-sync>Синхронизировать</button>'+(canUseAdmin?'<button data-v38-mode>'+(admin?'Режим пользователя':'Режим администратора')+'</button>':'')+'</div>';nav.innerHTML=html;nav.querySelectorAll('[data-v38-user]').forEach(function(b){b.onclick=function(){showUserView(b.dataset.v38User);renderAll();v38CloseMobileMenu()}});nav.querySelectorAll('[data-v38-admin]').forEach(function(b){b.onclick=function(){switchAdmin(b.dataset.v38Admin);v38CloseMobileMenu()}});nav.querySelectorAll('[data-v38-project]').forEach(function(b){b.onclick=function(){state.projectId=b.dataset.v38Project;state.folderId='root';switchAdmin('materials');showMaterialsList();renderProjects();renderMaterials();v38CloseMobileMenu()}});nav.querySelectorAll('[data-v38-project-menu]').forEach(function(b){b.onclick=function(){v38CloseMobileMenu();projectActions(b.dataset.v38ProjectMenu)}});var addProjectButton=nav.querySelector('[data-v38-add-project]');if(addProjectButton)addProjectButton.onclick=function(){v38CloseMobileMenu();projectModal()};var sync=nav.querySelector('[data-v38-sync]');if(sync)sync.onclick=function(){v38CloseMobileMenu();loadAll(true)};var mode=nav.querySelector('[data-v38-mode]');if(mode)mode.onclick=function(){setMode(admin?'user':'admin');v38CloseMobileMenu()}}
function v38EnsureMobileUi(){var button=$('#v38MobileMenuBtn'),layer=$('#v38MobileLayer'),nav=$('#v38MobileNav');if(button&&layer&&nav){if(!nav.childElementCount)v38RenderMobileMenu();return}if(button)button.remove();if(layer)layer.remove();var top=$('#topbar');if(!top)return;button=document.createElement('button');button.id='v38MobileMenuBtn';button.type='button';button.setAttribute('aria-label','Открыть меню');button.setAttribute('aria-expanded','false');button.innerHTML='<span></span><span></span><span></span>';top.appendChild(button);layer=document.createElement('div');layer.id='v38MobileLayer';layer.innerHTML='<button class="v38-mobile-shade" aria-label="Закрыть меню"></button><aside class="v38-mobile-drawer"><div class="v38-mobile-drawer-head"><b>Меню</b><button type="button" data-v38-close aria-label="Закрыть">×</button></div><nav id="v38MobileNav"></nav></aside>';document.body.appendChild(layer);button.onclick=function(){var open=layer.classList.toggle('open');button.setAttribute('aria-expanded',open?'true':'false');document.body.classList.toggle('v38-menu-open',open);v38RenderMobileMenu()};layer.querySelector('.v38-mobile-shade').onclick=v38CloseMobileMenu;layer.querySelector('[data-v38-close]').onclick=v38CloseMobileMenu;v38RenderMobileMenu()}
