/* v039: durable Bitrix.Disk media recovery and version placement */
function v39PortalOrigin(){
  try{if(window.BX24&&typeof BX24.getDomain==='function'){var domain=String(BX24.getDomain()||'').trim();if(domain)return new URL(/^https?:\/\//i.test(domain)?domain:'https://'+domain).origin}}catch(e){}
  try{if(document.referrer){var ref=new URL(document.referrer);if(/^https:$/.test(ref.protocol))return ref.origin}}catch(e){}
  return location.protocol==='https:'?location.origin:''
}
function v39SafeUrl(raw){raw=String(raw||'').trim().replace(/&amp;/gi,'&');if(!raw)return '';if(raw.indexOf('//')===0)raw='https:'+raw;try{var url=new URL(raw,v39PortalOrigin()||location.href);return url.protocol==='https:'?url.href:''}catch(e){return ''}};
function v39DiskFile(value){return value&&value.file||value&&value.result&&value.result.file||value&&value.result||value||{}}
function v39DiskLink(value){value=value&&value.result||value;return v39SafeUrl(typeof value==='string'?value:value&&(value.url||value.URL||value.EXTERNAL_LINK)||'')}
function v39MediaPanel(block,message){
  var body=block&&block.querySelector('.rtm-block-body');if(!body)return null;var panel=body.querySelector('.v39-media-error-panel');if(!panel){panel=document.createElement('div');panel.className='v39-media-error-panel';panel.contentEditable='false';panel.innerHTML='<b>Медиафайл временно недоступен</b><span></span><button type="button">Повторить загрузку</button>';body.appendChild(panel);panel.querySelector('button').onclick=function(){v39RetryMedia(block)}}panel.querySelector('span').textContent=message||'Обновляем ссылку на файл.';return panel
}
function v39SetMediaError(block,error,message){if(!block)return;block.classList.toggle('v39-media-error',!!error);if(error)v39MediaPanel(block,message);else{var panel=block.querySelector('.v39-media-error-panel');if(panel)panel.remove()}}
function v39ApplyMediaUrl(block,media,url,wasPlaying){
  url=v39SafeUrl(url);if(!media||!url)return;v39SetMediaError(block,false);if(media.tagName==='IMG'){media.removeAttribute('src');requestAnimationFrame(function(){media.setAttribute('src',url)})}else{media.setAttribute('src',url);media.load();if(wasPlaying&&media.play)media.play().catch(function(){})}
}
v37RefreshDiskBlock=async function(block,force){
  if(!block||!block.dataset.diskId||block._v39Refreshing)return false;var nowMs=Date.now(),last=Number(block._v39LastRefresh||0);if(!force&&nowMs-last<5000)return false;block._v39LastRefresh=nowMs;block._v39Refreshing=true;
  try{var file=v39DiskFile(await call('disk.file.get',{id:block.dataset.diskId})),fresh=v39SafeUrl(file.DOWNLOAD_URL||file.downloadUrl||file.DOWNLOAD_URI||file.DOWNLOAD_LINK||'');if(!fresh)throw new Error('Bitrix не вернул временную ссылку');var media=block.querySelector('img,video,audio'),wasPlaying=media&&media.tagName!=='IMG'&&!media.paused;v39ApplyMediaUrl(block,media,fresh,wasPlaying);return true}catch(e){v39SetMediaError(block,true,'Не удалось обновить ссылку Bitrix.Диска. Нажмите «Повторить загрузку».');console.warn('Bitrix.Disk media refresh failed',e);return false}finally{block._v39Refreshing=false}
};
function v39RetryMedia(block){var media=block&&block.querySelector('img,video,audio');if(!media)return;if(block.dataset.diskId){v39SetMediaError(block,false);v37RefreshDiskBlock(block,true)}else{var src=media.getAttribute('src');v39SetMediaError(block,false);if(media.tagName==='IMG'){media.removeAttribute('src');requestAnimationFrame(function(){media.setAttribute('src',src)})}else media.load()}}
function v39BindMediaBlock(block){
  if(!block)return;if(block.dataset.diskId){block.dataset.v37DiskError='1';block.dataset.v37DiskHydrated='1'}var media=block.querySelector('img,video,audio');if(!media)return;
  if(!media._v39MediaBound){media._v39MediaBound=true;var loaded=function(){v39SetMediaError(block,false)};media.addEventListener(media.tagName==='IMG'?'load':'loadedmetadata',loaded);media.addEventListener('canplay',loaded);media.addEventListener('error',function(){if(block.dataset.diskId)v37RefreshDiskBlock(block,true);else v39SetMediaError(block,true,'Проверьте доступность ссылки и повторите загрузку.')})}
  if(block.dataset.diskId&&!block._v39DiskHydrated){block._v39DiskHydrated=true;v37RefreshDiskBlock(block,true)}else if(media.tagName==='IMG'&&media.complete&&!media.naturalWidth)v39SetMediaError(block,true,'Изображение не загрузилось. Нажмите «Повторить загрузку».')
}
function v39RepairMedia(){document.querySelectorAll('.rtm-content-block.rtm-image-block,.rtm-content-block.rtm-audio-block,.rtm-content-block.rtm-video-block').forEach(v39BindMediaBlock)}
function v39EnsureVersionLabels(){
  var profile=document.querySelector('#userProfile .user-container');if(profile&&!profile.querySelector('.v39-profile-version')){var userVersion=document.createElement('div');userVersion.className='v39-version-label v39-profile-version';userVersion.textContent='Версия v045';profile.appendChild(userVersion)}
  var rail=document.querySelector('#adminApp .icon-rail');if(rail&&!rail.querySelector('.v39-admin-version')){var adminVersion=document.createElement('div');adminVersion.className='v39-version-label v39-admin-version';adminVersion.textContent='v49.2';adminVersion.title='Версия v49.2';rail.appendChild(adminVersion)}
}
